export const INGREDIENT_BY_ID: Record<string, Ingredient> = Object.fromEntries(INGREDIENTS.map((x) => [x.id, x]))

/** L'id con cui un ingrediente del frigo conta nelle ricette (le varianti contano come l'ingrediente base). */
export const recipeIdOf = (id: string) => INGREDIENT_BY_ID[id]?.as ?? id

